#!/usr/bin/env python3
"""Cyclopts CLI with TOML configuration support from [tool.mycli]."""

from pathlib import Path
from typing import Optional
from cyclopts import App

try:
    import tomllib
except ImportError:
    import tomli as tomllib


def load_config() -> dict:
    """Load configuration from [tool.mycli] in pyproject.toml."""
    pyproject_path = Path("pyproject.toml")
    if pyproject_path.exists():
        with open(pyproject_path, "rb") as f:
            data = tomllib.load(f)
            return data.get("tool", {}).get("mycli", {})
    return {}


# Create example pyproject.toml if it doesn't exist
if not Path("pyproject.toml").exists():
    Path("pyproject.toml").write_text("""
[tool.mycli]
name = "Alice"
verbose = false
output = "result.txt"
count = 3
""")

# Load config from pyproject.toml
config = load_config()

# Create cyclopts app
app = App()


@app.default
def greet(
    name: Optional[str] = None,
    verbose: Optional[bool] = None,
    output: Optional[str] = None,
):
    """Greet someone.

    CLI arguments override [tool.mycli] defaults in pyproject.toml.
    """
    # CLI values win; fall back to config; then hardcoded defaults
    name = name if name is not None else config.get("name", "World")
    verbose = verbose if verbose is not None else config.get("verbose", False)
    output = output if output is not None else config.get("output")

    message = f"Hello, {name}!"
    if verbose:
        message += " (verbose mode)"

    if output:
        Path(output).write_text(message)
        print(f"Saved to: {output}")
    else:
        print(message)


@app.command
def process(
    count: Optional[int] = None,
    name: Optional[str] = None,
):
    """Process items.

    CLI arguments override [tool.mycli] defaults.
    """
    count = count if count is not None else config.get("count", 1)
    name = name if name is not None else config.get("name", "default")
    print(f"Processing {count} item(s) for {name}")


@app.command
def show_config():
    """Show loaded configuration from [tool.mycli]."""
    if config:
        print("Configuration from [tool.mycli]:")
        for key, value in config.items():
            print(f"  {key}: {value}")
    else:
        print("No [tool.mycli] section found in pyproject.toml")


if __name__ == "__main__":
    app()

